class Builder {
  left: i32;
  seed: i32 = 7;
  constructor(left: i32) {
    this.left = left;
  }

  next(): i32 {
    this.seed = (this.seed * 1105 + 12345) % 65536;
    return this.seed >> 4;
  }
}

const child = (b: Builder, depth: i32): Node | null =>
  depth <= 0 || b.left <= 0 ? null : build(b, depth - 1);

const children = (b: Builder, depth: i32): Node[] => {
  const out: Node[] = [];
  if (depth > 0) {
    const n = b.next() % 4;
    for (let i = 0; i < n && b.left > 0; i++) {
      out.push(build(b, depth - 1));
    }
  }
  return out;
};

