export const main = (): void => {
  const b = new Builder(4000);
  const roots: Node[] = [];
  while (b.left > 0) {
    roots.push(build(b, 8));
  }
  const w = new Walk();
  const t = new Tally();
  for (const r of roots) {
    visit(r, w);
    tally(r, t);
  }
  console.log(`roots ${roots.length} nodes ${w.count} checksum ${w.sum}`);
  console.log(`flags ${t.flags} names ${t.names}`);
};
